"""Output-only invariant checks, applied to fuzz results."""
import hashlib, json
EMPTY='e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'
DISCARD={'BAD_HEADER','CLOSED','DROP_CID','NO_KEY','PN_RANGE','AUTH','DUPLICATE'}
ERROR={'FRAME_ENCODING_ERROR','PROTOCOL_VIOLATION','STREAM_STATE_ERROR','STREAM_LIMIT_ERROR','FINAL_SIZE_ERROR',
       'FLOW_CONTROL_ERROR','CONNECTION_ID_LIMIT_ERROR','KEY_UPDATE_ERROR'}
def check_trace(t, cfg, errs):
    def bad(msg): errs.append(msg)
    # packets
    seen_closed=False; close_seen=False
    per_dg={}
    for p in t['packets']:
        per_dg.setdefault(p['event'], []).append(p)
        if p['status']=='BAD_HEADER':
            if p['level'] is not None or p['pn'] is not None or p['epoch'] is not None or p['sha256'] is not None:
                bad('bad_header row must have nulls')
        else:
            if p['level'] not in ('I','H','A'): bad('level '+str(p['level']))
            if not isinstance(p['pn'], int) or p['pn']<0: bad('pn')
            if p['level']!='A' and p['epoch'] is not None: bad('epoch on long header')
            if p['status'] in ('OK','PEER_CLOSE'):
                if not p['sha256'] or len(p['sha256'])!=64: bad('accepted hash')
            elif p['sha256'] is not None: bad('hash on discarded '+p['status'])
            if p['status']=='AUTH' and p['epoch'] is not None: bad('epoch on AUTH')
            if p['status'] in ('CLOSED','DROP_CID','NO_KEY','PN_RANGE') and p['epoch'] is not None: bad('epoch on discard')
        if seen_closed and p['status'] not in DISCARD|{'CLOSED'} and p['status']!='BAD_HEADER':
            bad('packet after close not CLOSED: '+p['status'])
        if p['status'] in ERROR|{'PEER_CLOSE'}:
            if close_seen: bad('second close')
            close_seen=True; seen_closed=True
    if close_seen != (t['closed'] is not None): bad('closed row mismatch')
    if t['closed'] is not None:
        c=t['closed']
        if set(c)!={'event','packet','offset','code'}: bad('closed keys')
        if c['code'] not in ERROR|{'PEER_CLOSE'}: bad('closed code '+c['code'])
    # datagrams
    n_dg=sum(1 for e in cfg['events'] if 'datagram' in e)
    if len(t['datagrams'])!=n_dg: bad('datagram row count %d != %d'%(len(t['datagrams'],n_dg))
    for d in t['datagrams']:
        if set(d)!={'event','packets','accepted','bytes','sha256'}: bad('datagram keys')
        rows=per_dg.get(d['event'],[])
        if d['packets']!=len(rows): bad('datagram packets count')
        acc=sum(1 for r in rows if r['status'] in ('OK','PEER_CLOSE'))
        if d['accepted']!=acc: bad('datagram accepted')
        if acc==0:
            if d['bytes']!=0 or d['sha256']!=EMPTY: bad('empty datagram hash')
        elif len(d['sha256'])!=64: bad('datagram hash')
    # keys
    if set(t['keys'])-{'I','H','A'} or len(set(t['keys']))!=len(t['keys']): bad('keys')
    if t['keys']!=sorted(t['keys'], key='IHA'.index): bad('keys order')
    # received
    for lvl in 'IHA':
        exp=None
        seed=cfg['received'][lvl]
        if seed is not None: exp=seed
        for p in t['packets']:
            if p['level']==lvl and p['status'] in ('OK','PEER_CLOSE'):
                exp=p['pn'] if exp is None else max(exp,p['pn'])
        if t['received'][lvl]!=exp: bad('received %s %s != %s'%(lvl,t['received'][lvl],exp))
    # epochs
    eps=t['epochs']
    if [e['epoch'] for e in eps]!=sorted(e['epoch'] for e in eps): bad('epochs order')
    tot=sum(e['count'] for e in eps)
    accA=sum(1 for p in t['packets'] if p['level']=='A' and p['status'] in ('OK','PEER_CLOSE'))
    seedA=1 if cfg['received']['A'] is not None else 0
    if tot!=accA+seedA: bad('epoch count total %d != %d'%(tot,accA+seedA))
    for e in eps:
        if not (e['min']<=e['max'] and e['count']>=1): bad('epoch stats')
    # ordering across epochs
    for i in range(len(eps)):
        for j in range(i+1,len(eps)):
            if not eps[i]['max']<eps[j]['min']: bad('epoch ordering violated %s %s'%(eps[i],eps[j]))
    if eps and t['key_epoch'] not in [e['epoch'] for e in eps] and (accA+seedA)>0:
        bad('key_epoch not among epochs')
    # opened/used/streams
    used=sum(s['high'] for s in t['streams'])
    if used!=t['used']: bad('used %d != %d'%(used,t['used']))
    ids=[s['id'] for s in t['streams']]
    if ids!=sorted(ids) or len(set(ids))!=len(ids): bad('stream ids')
    ob=ou=0
    for s in t['streams']:
        if set(s)!={'id','high','final','reset','stop','send_max','ranges','unique','prefix','sha256'}: bad('stream keys')
        cat=s['id']%4; idx=s['id']//4
        if cat==0: ob=max(ob,idx+1)
        if cat==2: ou=max(ou,idx+1)
        if s['final'] is not None and s['high']>s['final']: bad('high>final')
        prev=None
        tot=0
        for a,b in s['ranges']:
            if a>=b: bad('empty range')
            if prev is not None and a<=prev: bad('unsorted/overlapping ranges')
            prev=b; tot+=b-a
        if tot!=s['unique']: bad('unique mismatch')
        # prefix
        p=0
        for a,b in s['ranges']:
            if a==p: p=b
            elif a>p: break
        if p!=s['prefix']: bad('prefix mismatch %d %d'%(p,s['prefix']))
        if s['prefix']==0 and s['sha256']!=EMPTY: bad('empty prefix hash')
    # opened may exceed explicit rows (implicit opening) but never less
    if t['opened']['bidi']<ob or t['opened']['uni']<ou: bad('opened too small')
    # crypto
    for c in t['crypto']:
        if set(c)!={'level','ranges','unique','prefix','sha256'}: bad('crypto keys')
        prev=None; tot=0
        for a,b in c['ranges']:
            if prev is not None and a<=prev: bad('crypto ranges')
            prev=b; tot+=b-a
        if tot!=c['unique']: bad('crypto unique')
        if c['prefix']==0 and c['sha256']!=EMPTY: bad('crypto empty hash')
    # acknowledged
    for a in t['acknowledged']:
        if set(a)!={'level','count','intervals','prefix','sha256','ecn'}: bad('ack keys')
        if len(a['ecn'])!=3: bad('ecn len')
        if a['count']==0 and (a['intervals']!=0 or a['sha256']!=EMPTY): bad('empty ack')
        if a['count']>0 and a['intervals']<1: bad('ack intervals')
        if a['prefix']>a['count']: bad('ack prefix')
        if a['count']==0 and a['sha256']!=EMPTY: bad('ack empty hash')
    # peer cids
    pcs=t['peer_cids']
    if [c['sequence'] for c in pcs]!=sorted(c['sequence'] for c in pcs): bad('peer cid order')
    if len(pcs)>cfg['limits']['cids']: bad('peer cid count over limit')
    if len({c['id'] for c in pcs})!=len(pcs): bad('duplicate active cid')
    for c in pcs:
        if set(c)!={'sequence','id','token'}: bad('peer cid keys')
        if c['sequence']<t['retire_prior_to']: bad('active below threshold')
        if c['id']!=c['id'].lower() or c['token']!=c['token'].lower(): bad('hex case')
        if len(c['token'])!=32: bad('token len')
    # retired local
    prev=None
    for a,b in t['retired_local']:
        if a>=b: bad('retired empty')
        if prev is not None and a<=prev: bad('retired merged/sorted')
        prev=b
        if not (0<=a<len(cfg['local']['cids'])): bad('retired range')
def check(batch, out, errs):
    if 'traces' not in out: errs.append('no traces: %s' % str(out)[:200]); return
    if len(out['traces'])!=len(batch['traces']): errs.append('trace count')
    for t,cfg in zip(out['traces'], batch['traces']):
        if set(t)!={'packets','datagrams','closed','keys','received','key_epoch','epochs','opened','used',
                    'send_max_data','send_max_streams','streams','crypto','acknowledged','peer_cids',
                    'retire_prior_to','retired_local'}:
            errs.append('result keys %s'%sorted(set(t)))
        check_trace(t,cfg,errs)
